class alarms_watchdog(object):
    """ Allows background watching for disallowed alarms in active alarms """

    ROBOT_LIBRARY_SCOPE = 'TEST SUITE'

    def __init__(self):
        self._allowed_alarms = []
        self._detected_alarms = []
        self._lost_alarms = []
        self._read_active_alarms = []
        self._disallowed_active_alarms = []
        self._watcher = None
        self._keep_watching = False
        self._interval = 0.0
        self._connection_timeout = 30
        self._reconnect = False
        self._callbacks = {}
        self._callbacks_threads = []
        self._bts_config = None
        self._bts = None
        self._bts_type = "BTS"
        self._bts_connection_name = 'alarms_watchdog_{}'.format(id(self))
        self._bts_connection_kwargs = {}
        self._latest_connection_error = None
        self._log_dir = ''
        self._logger = logging.getLogger()

    def watch_alarms(self, allowed_alarms=None, interval=2.0, bts_config=None, log_dir='', reconnect=False, timeout=30,
                     **connection_kwargs):
        """
        Starts watching active alarms on BTS for disallowed alarms.

        Doesn't block test execution, alarms watching is done in parallel with main thread.
        Must always be used together with stop_watching_alarms keyword, preferably put in test's teardown.
        After starting active alarms watch it will wait one interval for potential active alarms to be read from BTS.
        Works with gnB Classical, gNB Cloud and eNB BTS topologies.

        BTS is asked for current active alarms every time when time interval passes.
        Disallowed alarms are those which were not allowed either via param allowed_alarms or allow_alarm keyword.
        If disallowed alarm is detected then it is saved in watch history.
        If detected alarm stops being active then it is marked as lost in watch history.
        Detected disallowed alarms history can be checked with has_detected_alarms or check_detected_alarms keywords.

        :param allowed_alarms: list of alarms which will be skipped during active alarms check;
                               keyword create_alarm can be used to populate list of allowed alarms;
                               keyword allow_alarm can be used instead of this parameter before starting alarms watch;
                               defaults to None (no additional alarms will be considered as allowed)
        :type allowed_alarms: list(Alarm) or None
        :param interval: time interval (in seconds) between consecutive requests to BTS for active alarms;
                         accepts Robot string time format i.e. 1 min 30 sec; defaults to 2 sec
        :type interval: float or int or str
        :param bts_config: configuration object of BTS to which requests for active alarms will be sent;
                           should contain all data required to connect to given BTS;
                           supported BTS configuration classes: ClassicalBts, CloudBts, RealEnb;
                           defaults to None (ClassicalBts with default connection details will be used)
        :type bts_config: taf.config.testline.gnb.gnb.gNB, taf.config.testline.enb.RealEnb or None
        :param log_dir: path to directory where additional logs will be stored
        :type log_dir: str
        :param reconnect: if True then reconnection to BTS will be attempted after active alarms
                          could not be read from BTS due to API error;
                          failed reconnection attempts will not stop alarms watch;
                          it is recommended to use True if SW version on BTS will be changed while watching alarms;
                          defaults to False (no reconnection attempt)
        :type reconnect: bool
        :param timeout: time (in seconds) to wait for successful connection to BTS;
                        accepts Robot string time format i.e. 1 min 30 sec; defaults to 30 sec
        :type timeout: int or str
        :param connection_kwargs: additional parameters used when connecting to BTS, i.e. cu_id=0, du_id=0
        :raises WatchdogAlreadyStarted: when re-starting alarms watch was not preceded with stopping alarms watch
        :raises InvalidBtsType: when given bts_type is unsupported
        :raises BtsConnectionError: when connection to BTS cannot be established
        """
        self._check_for_already_started_watch()

        self._add_allowed_alarms(allowed_alarms)
        self._interval = time_to_seconds(interval)
        self._connection_timeout = time_to_seconds(timeout, round_to=0)
        self._reconnect = reconnect

        self._configure_bts(bts_config, **connection_kwargs)
        self._connect_to_bts(log_dir, **connection_kwargs)
        self._start_watcher()

        self._log_info_message('Watching alarms on {}{} with interval: {}s and allowed alarms: {}'.format(
            self._bts_type, self._get_formatted_bts_ip_if_exists(), self._interval, self._allowed_alarms))

    def allow_alarm(self, alarm_id=None, fault_id=None, fault_name=None, hw_path=None, severity=None, reason=None,
                    unit_path=None, impacted_cells_count=None, fault_signature=None):
        """
        Adds new alarm into list of alarms which will be skipped during active alarms check.

        Can be used to dynamically change allowed alarms during test case execution.
        Allowed alarm must have at least one parameter set to value different than None.
        When allowed alarm will be compared with active alarms, then only parameters which are not None will be used
        during comparison.

        :param alarm_id: used during comparison with alarm ID of active alarms; defaults to None (not used)
        :type alarm_id: str or None
        :param fault_id: used during comparison with fault ID of active alarms; defaults to None (not used)
        :type fault_id: str or None
        :param fault_name: used during comparison with fault name of active alarms; defaults to None (not used)
        :type fault_name: str or None
        :param hw_path: used during comparison with HW path of active alarms;
                        can be used only for ClassicalBts and RealEnb, unavailable for CloudBts;
                        defaults to None (not used)
        :type hw_path: str, re.Pattern or None
        :param severity: used during comparison with severity of active alarms; defaults to None (not used)
        :type severity: str or None
        :param reason: used during comparison with reason of active alarms,
                       i.e. 'Failed sanity check point results: /MRBTS-1/RAT-1/RUNTIME_VIEW-1/MRBTS_R-1:{1b, 2}';
                       can be used only for ClassicalBts and RealEnb, unavailable for CloudBts;
                       defaults to None (not used)
        :type reason: str, re.Pattern or None
        :param unit_path: used during comparison with unit path of active alarms; defaults to None (not used)
        :type unit_path: str, re.Pattern or None
        :param impacted_cells_count: used during comparison with impacted cells count of active alarms;
                                     can be used only for ClassicalBts and RealEnb, unavailable for CloudBts;
                                     defaults to None (not used)
        :type impacted_cells_count: str or None
        :param fault_signature: used during comparison with fault signature of active alarms;
                                i.e. {'category': 'POWER_OFF',
                                      'component': '1M203838370',
                                      'date': '20230519090516.000+0300'}
                                comparison will take into account only provided attributes of fault signature;
                                can be used only for ClassicalBts and RealEnb, unavailable for CloudBts;
                                defaults to None (not used)
        :type fault_signature: dict or None
        :raises InvalidAlarm: when all of allowed alarm's parameters will be None
        """
        alarm = Alarm(alarm_id=alarm_id,
                      fault_id=fault_id,
                      fault_name=fault_name,
                      hw_path=hw_path,
                      severity=severity,
                      reason=reason,
                      unit_path=unit_path,
                      impacted_cells_count=impacted_cells_count,
                      fault_signature=fault_signature)
        self._log_info_message('Allowing {} on {}{}'.format(
            alarm, self._bts_type, self._get_formatted_bts_ip_if_exists())
        )

        if not self._is_alarm_already_allowed(alarm):
            self._allowed_alarms.append(alarm)

        self._log_allowed_alarms()

    def disallow_alarm(self, alarm_id=None, fault_id=None, fault_name=None, hw_path=None, severity=None, reason=None,
                       unit_path=None, impacted_cells_count=None, fault_signature=None):
        """
        Removes alarm from list of alarms which will be skipped during active alarms check.

        Can be used to dynamically change allowed alarms during test case execution.
        Disallowed alarm must have at least one parameter set to value different than None.
        Disallowed alarm will be matched with allowed alarm (to remove) only by parameters which are not None.
        When disallowed alarm will not be matched with any of current allowed alarms then no alarm will be disallowed.

        :param alarm_id: used during comparison with alarm ID of allowed alarms; defaults to None (not used)
        :type alarm_id: str or None
        :param fault_id: used during comparison with fault ID of allowed alarms; defaults to None (not used)
        :type fault_id: str or None
        :param fault_name: used during comparison with fault name of allowed alarms; defaults to None (not used)
        :type fault_name: str or None
        :param hw_path: used during comparison with HW path of allowed alarms;
                        can be used only for ClassicalBts and RealEnb, unavailable for CloudBts;
                        defaults to None (not used)
        :type hw_path: str, re.Pattern or None
        :param severity: used during comparison with severity of active alarms; defaults to None (not used)
        :type severity: str or None
        :param reason: used during comparison with reason of active alarms,
                       i.e. 'Failed sanity check point results: /MRBTS-1/RAT-1/RUNTIME_VIEW-1/MRBTS_R-1:{1b, 2}';
                       can be used only for ClassicalBts and RealEnb, unavailable for CloudBts;
                       defaults to None (not used)
        :type reason: str, re.Pattern or None
        :param unit_path: used during comparison with unit path of active alarms; defaults to None (not used)
        :type unit_path: str, re.Pattern or None
        :param impacted_cells_count: used during comparison with impacted cells count of active alarms;
                                     can be used only for ClassicalBts and RealEnb, unavailable for CloudBts;
                                     defaults to None (not used)
        :type impacted_cells_count: str or None
        :param fault_signature: used during comparison with fault signature of active alarms;
                                i.e. {'category': 'POWER_OFF',
                                      'component': '1M203838370',
                                      'date': '20230519090516.000+0300'}
                                comparison will take into account only provided attributes of fault signature;
                                can be used only for ClassicalBts and RealEnb, unavailable for CloudBts;
                                defaults to None (not used)
        :type fault_signature: dict or None
        :raises InvalidAlarm: when all of disallowed alarm's parameters will be None
        """
        alarm = Alarm(alarm_id=alarm_id,
                      fault_id=fault_id,
                      fault_name=fault_name,
                      hw_path=hw_path,
                      severity=severity,
                      reason=reason,
                      unit_path=unit_path,
                      impacted_cells_count=impacted_cells_count,
                      fault_signature=fault_signature)
        self._log_info_message('Disallowing {} on {}{}'.format(
            alarm, self._bts_type, self._get_formatted_bts_ip_if_exists())
        )

        self._allowed_alarms = [allowed_alarm for allowed_alarm in self._allowed_alarms if allowed_alarm != alarm]
        self._log_allowed_alarms()

        self._wait()

    def disallow_all_alarms(self):
        """
        Removes all alarms from list of alarms which will be skipped during active alarms check.

        Can be used to dynamically change allowed alarms during test case execution.
        """
        self._log_info_message('Disallowing all alarms on {}{}'.format(
            self._bts_type, self._get_formatted_bts_ip_if_exists())
        )

        self._allowed_alarms = []
        self._log_allowed_alarms()

        self._wait()

    def disallow_all_alarms_except_of(self, alarms):
        """
        Removes all alarms from list of alarms which will be skipped during active alarms check
        EXCEPT OF alarms provided on alarms list.

        Can be used to dynamically change allowed alarms during test case execution.

        :param alarms: list of alarms which, if previously allowed, will remain allowed.
                       keyword create_alarm can be used to populate list of alarms;
        :type alarms: list(Alarm)
        """
        self._log_info_message('Disallowing all alarms except of {} on {}{}'.format(
            alarms, self._bts_type, self._get_formatted_bts_ip_if_exists())
        )

        self._allowed_alarms = [allowed_alarm for allowed_alarm in self._allowed_alarms if allowed_alarm in alarms]
        self._log_allowed_alarms()

        self._wait()

    def check_detected_alarms(self):
        """
        Checks whether watch history contains any detected disallowed alarm.

        Alarms watching will be continued despite any disallowed alarm being detected or not.
        Before using this method alarms watchdog needs to be started - watch_alarms method must be used first.

        :raises WatchdogNotStarted: when performing this action was not preceded with starting alarms watch
        :raises DisallowedAlarmsDetected: when watch history contains at least one detected disallowed alarm
        """
        self._log_info_message('Checking detected alarms on {}{}'.format(
            self._bts_type, self._get_formatted_bts_ip_if_exists())
        )
        self._check_for_not_started_watch(self.check_detected_alarms.__name__)
        self._log_read_active_alarms()
        self._log_latest_connection_error()

        if self.has_detected_alarms():
            report = self._get_report()
            raise DisallowedAlarmsDetected(report)
        else:
            self._log_info_message('No disallowed alarms detected on {}{}'.format(
                self._bts_type, self._get_formatted_bts_ip_if_exists())
            )

    def has_detected_alarms(self):
        """
        Checks whether watch history contains any detected disallowed alarm.

        Regardless of whether any disallowed alarm was detected or not, alarms watching is continued.
        Before using this method alarms watchdog needs to be started - watch_alarms method must be used first.

        :return: True if watch history contains any detected disallowed alarm, False otherwise.
        :rtype: bool
        :raises WatchdogNotStarted: when performing this action was not preceded with starting alarms watch
        """
        self._check_for_not_started_watch(self.has_detected_alarms.__name__)

        has_detected_alarms = bool(self._detected_alarms)
        self._log_info_message('There are {} detected alarms on {}{}'.format(
            'some' if has_detected_alarms else 'no', self._bts_type, self._get_formatted_bts_ip_if_exists())
        )
        self._log_read_active_alarms()
        self._log_latest_connection_error()

        return has_detected_alarms

    def was_alarm_detected(self, alarm_id=None, fault_id=None, fault_name=None, hw_path=None, severity=None,
                           reason=None, unit_path=None, impacted_cells_count=None, fault_signature=None):
        """
        Checks whether watch history contains detected disallowed alarm with given attributes.

        Before using this method alarms watchdog needs to be started - watch_alarms method must be used first.

        :param alarm_id: used during comparison with alarm ID of detected alarms; defaults to None (not used)
        :type alarm_id: str or None
        :param fault_id: used during comparison with fault ID of detected alarms; defaults to None (not used)
        :type fault_id: str or None
        :param fault_name: used during comparison with fault name of detected alarms; defaults to None (not used)
        :type fault_name: str or None
        :param hw_path: used during comparison with HW path of detected alarms;
                        can be used only for ClassicalBts and RealEnb, unavailable for CloudBts;
                        defaults to None (not used)
        :type hw_path: str, re.Pattern or None
        :param severity: used during comparison with severity of active alarms; defaults to None (not used)
        :type severity: str or None
        :param reason: used during comparison with reason of active alarms,
                       i.e. 'Failed sanity check point results: /MRBTS-1/RAT-1/RUNTIME_VIEW-1/MRBTS_R-1:{1b, 2}';
                       can be used only for ClassicalBts and RealEnb, unavailable for CloudBts;
                       defaults to None (not used)
        :type reason: str, re.Pattern or None
        :return: If provided Alarm was detected during alarms watch then True will be returned, False otherwise.
        :rtype: Bool
        :param unit_path: used during comparison with unit path of active alarms; defaults to None (not used)
        :type unit_path: str, re.Pattern or None
        :param impacted_cells_count: used during comparison with impacted cells count of active alarms;
                                     can be used only for ClassicalBts and RealEnb, unavailable for CloudBts;
                                     defaults to None (not used)
        :type impacted_cells_count: str or None
        :param fault_signature: used during comparison with fault signature of active alarms;
                                i.e. {'category': 'POWER_OFF',
                                      'component': '1M203838370',
                                      'date': '20230519090516.000+0300'}
                                comparison will take into account only provided attributes of fault signature;
                                can be used only for ClassicalBts and RealEnb, unavailable for CloudBts;
                                defaults to None (not used)
        :type fault_signature: dict or None
        :raises WatchdogNotStarted: when performing this action was not preceded with starting alarms watch
        :raises InvalidAlarm: when all of provided alarm's parameters will be None
        """
        self._check_for_not_started_watch(self.was_alarm_detected.__name__)

        expected_detected_alarm = DetectedAlarm(detection_time=None,
                                                alarm_id=alarm_id,
                                                fault_id=fault_id,
                                                fault_name=fault_name,
                                                hw_path=hw_path,
                                                severity=severity,
                                                reason=reason,
                                                unit_path=unit_path,
                                                impacted_cells_count=impacted_cells_count,
                                                fault_signature=fault_signature)
        self._log_info_message('Checking if {} was detected on {}{}'.format(
            repr(expected_detected_alarm), self._bts_type, self._get_formatted_bts_ip_if_exists())
        )
        self._log_read_active_alarms()
        self._log_latest_connection_error()

        return expected_detected_alarm in self._detected_alarms

    def is_alarm_active(self, alarm_id=None, fault_id=None, fault_name=None, hw_path=None, severity=None, reason=None,
                        unit_path=None, impacted_cells_count=None, fault_signature=None):
        """
        Checks whether alarm with given attributes is currently active on BTS.

        Before using this method alarms watchdog needs to be started - watch_alarms method must be used first.

        :param alarm_id: used during comparison with alarm ID of active alarms; defaults to None (not used)
        :type alarm_id: str or None
        :param fault_id: used during comparison with fault ID of active alarms; defaults to None (not used)
        :type fault_id: str or None
        :param fault_name: used during comparison with fault name of active alarms; defaults to None (not used)
        :type fault_name: str or None
        :param hw_path: used during comparison with HW path of active alarms;
                        can be used only for ClassicalBts and RealEnb, unavailable for CloudBts;
                        defaults to None (not used)
        :type hw_path: str, re.Pattern or None
        :param severity: used during comparison with severity of active alarms; defaults to None (not used)
        :type severity: str or None
        :param reason: used during comparison with reason of active alarms,
                       i.e. 'Failed sanity check point results: /MRBTS-1/RAT-1/RUNTIME_VIEW-1/MRBTS_R-1:{1b, 2}';
                       can be used only for ClassicalBts and RealEnb, unavailable for CloudBts;
                       defaults to None (not used)
        :type reason: str, re.Pattern or None
        :return:  If provided Alarm is currently active on BTS then True will be returned, False otherwise.
        :rtype: Bool
        :param unit_path: used during comparison with unit path of active alarms; defaults to None (not used)
        :type unit_path: str, re.Pattern or None
        :param impacted_cells_count: used during comparison with impacted cells count of active alarms;
                                     can be used only for ClassicalBts and RealEnb, unavailable for CloudBts;
                                     defaults to None (not used)
        :type impacted_cells_count: str or None
        :param fault_signature: used during comparison with fault signature of active alarms;
                                i.e. {'category': 'POWER_OFF',
                                      'component': '1M203838370',
                                      'date': '20230519090516.000+0300'}
                                comparison will take into account only provided attributes of fault signature;
                                can be used only for ClassicalBts and RealEnb, unavailable for CloudBts;
                                defaults to None (not used)
        :raises WatchdogNotStarted: when performing this action was not preceded with starting alarms watch
        :raises InvalidAlarm: when all of provided alarm's parameters will be None
        """
        self._check_for_not_started_watch(self.is_alarm_active.__name__)

        active_alarm_to_check = Alarm(alarm_id=alarm_id,
                                      fault_id=fault_id,
                                      fault_name=fault_name,
                                      hw_path=hw_path,
                                      severity=severity,
                                      reason=reason,
                                      unit_path=unit_path,
                                      impacted_cells_count=impacted_cells_count,
                                      fault_signature=fault_signature)
        self._log_info_message('Checking if {} is active on {}{}'.format(
            active_alarm_to_check, self._bts_type, self._get_formatted_bts_ip_if_exists())
        )
        self._log_read_active_alarms()
        self._log_latest_connection_error()

        return self._is_alarm_active(active_alarm_to_check)

    def run_when_alarm_detected(self, trigger_alarms, callback, *args, **kwargs):
        """
        Registers callback with its args and kwargs to be called when any of trigger alarms is detected and disallowed.

        IMPORTANT: can't be used in Robot code, it will work only when called in Python code.
        Must be used together with watch_alarms to be able to trigger callback on detected alarm.
        If trigger alarm is not active on BTS then callback will not be called.
        If trigger alarm is active but allowed then callback will not be called.
        If trigger alarm is detected after it was lost then callback will be run each time when alarm is detected.
        If trigger alarm is detected before callback is registered then it will not be called.
        One alarm can trigger multiple different callbacks.
        One callback can be triggered by multiple different alarms.
        Each alarm, when detected, will trigger all appropriate callbacks once.
        Callback will be run in separate thread - it will not stop further alarm detection.

        :param trigger_alarms: list of alarms which, when disallowed and detected, will trigger callback execution;
                               when empty list or None is provided then any detected alarm will trigger callback;
        :type trigger_alarms: list(Alarm) or None
        :param callback: callable object (in most cases a function); it will NOT accept Robot keyword
        :type callback: Callable
        :param args: positional arguments which will be passed to callback
        :param kwargs: keyword arguments which will be passed to callback
        :raises InvalidCallback: when given callback is not callable
        """
        if not callable(callback):
            raise InvalidCallback(
                "Callback '{}' {} is not callable, it should be i.e. a function".format(callback, type(callback)))

        self._register_callback(trigger_alarms, callback, args, kwargs)

        msg = "following disallowed alarms are detected: {}".format(trigger_alarms) if trigger_alarms \
            else "any disallowed alarm is detected"

        self._log_info_message("Callback {} with args {} and kwargs {} registered to be run when {} on {}{}".format(
            callback, args, kwargs, msg, self._bts_type, self._get_formatted_bts_ip_if_exists()))

        self._log_debug_message("Registered callbacks on {}{}: {}".format(
            self._bts_type, self._get_formatted_bts_ip_if_exists(), self._callbacks))

    def stop_watching_alarms(self):
        """
        Stops watching active alarms on BTS for disallowed alarms.

        Required to use every time when watch_alarms keyword is used.
        Stops alarms watching sub-thread which was run in background and disconnects from BTS,
        so it is recommended to use it in test's teardown.
        It is allowed to use this keyword even if alarms watching was already stopped before (or not started at all).
        """
        self._log_info_message('Stopping alarms watch on {}{}'.format(
            self._bts_type, self._get_formatted_bts_ip_if_exists())
        )
        self._log_read_active_alarms()
        self._log_latest_connection_error()
        self._stop_watcher()
        self._disconnect_from_bts()
        self._reset()

    def get_allowed_alarms(self):
        """
        Returns list of alarms which will be skipped during active alarms check.

        :return: list of currently allowed alarms
        :rtype: list(Alarms)
        """
        self._log_info_message("Currently allowed alarms on {}{}: {}".format(
            self._bts_type, self._get_formatted_bts_ip_if_exists(), self._allowed_alarms)
        )
        return self._allowed_alarms

    def get_detected_alarms(self):
        """
        Returns list of alarms which were detected during active alarms check.

        Before using this method alarms watchdog needs to be started - watch_alarms method must be used first.

        :return: list of currently detected alarms
        :rtype: list(Alarms)
        :raises WatchdogNotStarted: when performing this action was not preceded with starting alarms watch
        """
        self._check_for_not_started_watch(self.get_detected_alarms.__name__)

        self._log_info_message("Currently detected alarms on {}{}: {}".format(
            self._bts_type, self._get_formatted_bts_ip_if_exists(), self._detected_alarms)
        )
        self._log_read_active_alarms()
        self._log_latest_connection_error()

        return self._detected_alarms

    def get_active_alarms(self):
        """
        Returns list of alarms which are currently active.

        Before using this method alarms watchdog needs to be started - watch_alarms method must be used first.

        :return: list of currently active alarms
        :rtype: list(Alarms)
        :raises WatchdogNotStarted: when performing this action was not preceded with starting alarms watch
        """
        self._check_for_not_started_watch(self.get_active_alarms.__name__)

        self._log_info_message("Currently active alarms on {}{}: {}".format(
            self._bts_type, self._get_formatted_bts_ip_if_exists(), self._read_active_alarms)
        )
        self._log_latest_connection_error()

        return self._read_active_alarms

    def wait_for_active_alarm(self, alarm_id=None, fault_id=None, fault_name=None, hw_path=None, severity=None,
                              reason=None, unit_path=None, impacted_cells_count=None, fault_signature=None, timeout=10):
        """
        Waits for alarm with given attributes to become active on BTS.

        Before using this method alarms watchdog needs to be started - watch_alarms method must be used first.

        :param alarm_id: used during comparison with alarm ID of active alarms; defaults to None (not used).
        :type alarm_id: str or None
        :param fault_id: used during comparison with fault ID of active alarms; defaults to None (not used).
        :type fault_id: str or None
        :param fault_name: used during comparison with fault name of active alarms; defaults to None (not used).
        :type fault_name: str or None
        :param hw_path: used during comparison with HW path of active alarms;
                        can be used only for ClassicalBts and RealEnb, unavailable for CloudBts;
                        defaults to None (not used).
        :type hw_path: str, re.Pattern or None
        :param severity: used during comparison with severity of active alarms; defaults to None (not used)
        :type severity: str or None
        :param reason: used during comparison with reason of active alarms,
                       i.e. 'Failed sanity check point results: /MRBTS-1/RAT-1/RUNTIME_VIEW-1/MRBTS_R-1:{1b, 2}';
                       can be used only for ClassicalBts and RealEnb, unavailable for CloudBts;
                       defaults to None (not used)
        :type reason: str, re.Pattern or None
        :param unit_path: used during comparison with unit path of active alarms; defaults to None (not used)
        :type unit_path: str, re.Pattern or None
        :param impacted_cells_count: used during comparison with impacted cells count of active alarms;
                                     can be used only for ClassicalBts and RealEnb, unavailable for CloudBts;
                                     defaults to None (not used)
        :type impacted_cells_count: str or None
        :param fault_signature: used during comparison with fault signature of active alarms;
                                i.e. {'category': 'POWER_OFF',
                                      'component': '1M203838370',
                                      'date': '20230519090516.000+0300'}
                                comparison will take into account only provided attributes of fault signature;
                                can be used only for ClassicalBts and RealEnb, unavailable for CloudBts;
                                defaults to None (not used)
        :type fault_signature: dict or None
        :param timeout: total time to wait for alarm with given attributes to become active on BTS.
                        Accepts Robot string time format i.e. 1 min 20 sec; defaults to 10 seconds.
        :type timeout: str, int
        :return: True if alarm becomes active
        :rtype: Bool
        :raises WatchdogNotStarted: when performing this action was not preceded with starting alarms watch
        :raises AlarmInactive: if alarm with provided attributes won't appear before timeout
        """
        self._check_for_not_started_watch(self.wait_for_active_alarm.__name__)

        expected_alarm = Alarm(alarm_id=alarm_id,
                               fault_id=fault_id,
                               fault_name=fault_name,
                               hw_path=hw_path,
                               severity=severity,
                               reason=reason,
                               unit_path=unit_path,
                               impacted_cells_count=impacted_cells_count,
                               fault_signature=fault_signature)
        timeout = time_to_seconds(timeout)

        self._log_info_message('Waiting for active {} on {}{} with {} sec timeout'.format(
            expected_alarm, self._bts_type, self._get_formatted_bts_ip_if_exists(), timeout))
        self._log_read_active_alarms()
        self._log_latest_connection_error()

        if self._wait_for(self._is_alarm_active, expected_alarm, timeout):
            return True

        raise AlarmInactive("Alarm {0} was not active after {1}s timeout.".format(expected_alarm, timeout))

    def wait_for_active_alarms(self, alarms, timeout=10):
        """
        Waits for all provided alarms to become active on BTS.

        Before using this method alarms watchdog needs to be started - watch_alarms method must be used first.

        :param alarms: list of alarms which presence will be checked on BTS.
        :type alarms: list(Alarm)
        :param timeout: total time to wait for alarm with given attributes to become active on BTS.
                        Accepts Robot string time format i.e. 1 min 20 sec; defaults to 10 seconds.
        :type timeout: str, int
        :return: True if all alarms become active
        :rtype: Bool
        :raises WatchdogNotStarted: when performing this action was not preceded with starting alarms watch
        :raises AlarmInactive: if alarms with provided attributes won't appear before timeout
        """
        self._check_for_not_started_watch(self.wait_for_active_alarms.__name__)

        timeout = time_to_seconds(timeout)
        self._log_info_message('Waiting for active {} on {}{} with {} sec timeout'.format(
            alarms, self._bts_type, self._get_formatted_bts_ip_if_exists(), timeout))
        self._log_read_active_alarms()
        self._log_latest_connection_error()

        if self._wait_for(self._are_alarms_active, alarms, timeout):
            return True

        not_detected_alarms = [alarm for alarm in alarms if alarm not in self._read_active_alarms]
        raise AlarmInactive("Alarms {0} were not active after {1}s timeout.".format(not_detected_alarms, timeout))

    def wait_for_inactive_alarm(self, alarm_id=None, fault_id=None, fault_name=None, hw_path=None, severity=None,
                                reason=None, unit_path=None, impacted_cells_count=None, fault_signature=None,
                                timeout=10):
        """
        Waits for alarm with given attributes to become inactive on BTS.

        Before using this method alarms watchdog needs to be started - watch_alarms method must be used first.

        :param alarm_id: used during comparison with alarm ID of active alarms; defaults to None (not used).
        :type alarm_id: str or None
        :param fault_id: used during comparison with fault ID of active alarms; defaults to None (not used).
        :type fault_id: str or None
        :param fault_name: used during comparison with fault name of active alarms; defaults to None (not used).
        :type fault_name: str or None
        :param hw_path: used during comparison with HW path of active alarms;
                        can be used only for ClassicalBts and RealEnb, unavailable for CloudBts;
                        defaults to None (not used).
        :type hw_path: str, re.Pattern or None
        :param severity: used during comparison with severity of active alarms; defaults to None (not used)
        :type severity: str or None
        :param reason: used during comparison with reason of active alarms,
                       i.e. 'Failed sanity check point results: /MRBTS-1/RAT-1/RUNTIME_VIEW-1/MRBTS_R-1:{1b, 2}';
                       can be used only for ClassicalBts and RealEnb, unavailable for CloudBts;
                       defaults to None (not used)
        :type reason: str, re.Pattern or None
        :param unit_path: used during comparison with unit path of active alarms; defaults to None (not used)
        :type unit_path: str, re.Pattern or None
        :param impacted_cells_count: used during comparison with impacted cells count of active alarms;
                                     can be used only for ClassicalBts and RealEnb, unavailable for CloudBts;
                                     defaults to None (not used)
        :type impacted_cells_count: str or None
        :param fault_signature: used during comparison with fault signature of active alarms;
                                i.e. {'category': 'POWER_OFF',
                                      'component': '1M203838370',
                                      'date': '20230519090516.000+0300'}
                                comparison will take into account only provided attributes of fault signature;
                                can be used only for ClassicalBts and RealEnb, unavailable for CloudBts;
                                defaults to None (not used)
        :type fault_signature: dict or None
        :param timeout: total time to wait for alarm with given attributes to become inactive on BTS.
                        Accepts Robot string time format i.e. 1 min 20 sec; defaults to 10 seconds.
        :type timeout: str, int
        :return: True if alarm becomes inactive
        :rtype: Bool
        :raises WatchdogNotStarted: when performing this action was not preceded with starting alarms watch
        :raises AlarmActive: if alarm with provided attributes won't disappear before timeout
        """
        self._check_for_not_started_watch(self.wait_for_inactive_alarm.__name__)

        alarm_to_check = Alarm(alarm_id=alarm_id,
                               fault_id=fault_id,
                               fault_name=fault_name,
                               hw_path=hw_path,
                               severity=severity,
                               reason=reason,
                               unit_path=unit_path,
                               impacted_cells_count=impacted_cells_count,
                               fault_signature=fault_signature)
        timeout = time_to_seconds(timeout)

        self._log_info_message('Waiting for inactive {} on {}{} with {} sec timeout'.format(
            alarm_to_check, self._bts_type, self._get_formatted_bts_ip_if_exists(), timeout))
        self._log_read_active_alarms()
        self._log_latest_connection_error()

        if self._wait_for(self._is_alarm_inactive, alarm_to_check, timeout):
            return True

        raise AlarmActive("Alarm {0} was still active after {1}s timeout.".format(alarm_to_check, timeout))

    def wait_for_inactive_alarms(self, alarms, timeout=10):
        """
        Waits for all provided alarms to become inactive on BTS.

        Before using this method alarms watchdog needs to be started - watch_alarms method must be used first.

        :param alarms: list of alarms which absence will be checked on BTS.
        :type alarms: list(Alarm)
        :param timeout: total time to wait for alarms with given attributes to become inactive on BTS.
                        Accepts Robot string time format i.e. 1 min 20 sec; defaults to 10 seconds.
        :type timeout:  str, int
        :return: True if all alarms become inactive.
        :rtype: Bool
        :raises WatchdogNotStarted: when performing this action was not preceded with starting alarms watch
        :raises AlarmActive: if alarms with provided attributes won't disappear before timeout.
        """
        self._check_for_not_started_watch(self.wait_for_inactive_alarms.__name__)

        timeout = time_to_seconds(timeout)
        self._log_info_message('Waiting for inactive {} on {}{} with {} sec timeout'.format(
            alarms, self._bts_type, self._get_formatted_bts_ip_if_exists(), timeout))
        self._log_read_active_alarms()
        self._log_latest_connection_error()

        if self._wait_for(self._are_alarms_inactive, alarms, timeout):
            return True

        still_active_alarms = [alarm for alarm in alarms if alarm in self._read_active_alarms]
        raise AlarmActive("Alarms {0} were still active after {1}s timeout.".format(still_active_alarms, timeout))

    def create_alarm(self, alarm_id=None, fault_id=None, fault_name=None, hw_path=None, severity=None, reason=None,
                     unit_path=None, impacted_cells_count=None, fault_signature=None):
        """
        Creates and returns instance of Alarm class with given parameters.
        Can be used with watch_alarms keyword to populate list of allowed alarms.

        :param alarm_id: used during comparison with alarm ID of active alarms; defaults to None (not used)
        :type alarm_id: str or None
        :param fault_id: used during comparison with fault ID of active alarms; defaults to None (not used)
        :type fault_id: str or None
        :param fault_name: used during comparison with fault name of active alarms; defaults to None (not used)
        :type fault_name: str or None
        :param hw_path: used during comparison with HW path of active alarms;
                        can be used only for ClassicalBts and RealEnb, unavailable for CloudBts;
                        defaults to None (not used)
        :type hw_path: str, re.Pattern or None
        :param severity: used during comparison with severity of active alarms; defaults to None (not used)
        :type severity: str or None
        :param reason: used during comparison with reason of active alarms,
                       i.e. 'Failed sanity check point results: /MRBTS-1/RAT-1/RUNTIME_VIEW-1/MRBTS_R-1:{1b, 2}';
                       can be used only for ClassicalBts and RealEnb, unavailable for CloudBts;
                       defaults to None (not used)
        :type reason: str, re.Pattern or None
        :param unit_path: used during comparison with unit path of active alarms; defaults to None (not used)
        :type unit_path: str, re.Pattern or None
        :param impacted_cells_count: used during comparison with impacted cells count of active alarms;
                                     can be used only for ClassicalBts and RealEnb, unavailable for CloudBts;
                                     defaults to None (not used)
        :type impacted_cells_count: str or None
        :param fault_signature: used during comparison with fault signature of active alarms;
                                i.e. {'category': 'POWER_OFF',
                                      'component': '1M203838370',
                                      'date': '20230519090516.000+0300'}
                                comparison will take into account only provided attributes of fault signature;
                                can be used only for ClassicalBts and RealEnb, unavailable for CloudBts;
                                defaults to None (not used)
        :type fault_signature: dict or None
        :return: alarm with given parameters
        :rtype: Alarm
        :raises InvalidAlarm: when all of alarm's parameters will be None
        """
        alarm = Alarm(alarm_id, fault_id, fault_name, hw_path, severity, reason, unit_path, impacted_cells_count,
                      fault_signature)
        self._log_info_message('Created {}'.format(alarm))
        return alarm

    def _check_for_not_started_watch(self, action_name):
        if not self._keep_watching:
            raise WatchdogNotStarted(
                "Before using '{}' alarms watch must be started first - use watch_alarms".format(action_name))

    def _check_for_already_started_watch(self):
        if self._keep_watching:
            raise WatchdogAlreadyStarted(
                'Before re-starting alarms watch it must be stopped first - use stop_watching_alarms')

    def _add_allowed_alarms(self, allowed_alarms):
        if allowed_alarms is not None:
            not_already_allowed = [alarm for alarm in allowed_alarms if not self._is_alarm_already_allowed(alarm)]
            self._allowed_alarms.extend(not_already_allowed)

    def _configure_bts(self, bts_config, **kwargs):
        self._bts_config = bts_config
        self._bts_type = self._get_bts_type()
        self._bts = BtsFactory.get_bts(self._bts_type, **kwargs)

    def _get_bts_type(self):
        if self._bts_config == 'Mock':
            return self._bts_config
        elif self._bts_config is None:
            return 'ClassicalBts'
        else:
            return self._bts_config.__class__.__name__

    def _connect_to_bts(self, log_dir, **kwargs):
        try:
            self._bts.connect_to(self._bts_config, self._bts_connection_name, log_dir=log_dir, timeout=self._connection_timeout, **kwargs)
        except (AdminApiConnectionClosedException, AdminApiTerminatedException, ConnectionError) as api_error:
            raise BtsConnectionError('Alarms Watchdog cannot connect to BTS due to following API error: {}'.format(
                api_error))

        self._log_dir = log_dir
        self._bts_connection_kwargs = kwargs

    def _start_watcher(self):
        self._log_info_message('Starting watcher thread on {}{}'.format(
            self._bts_type, self._get_formatted_bts_ip_if_exists())
        )
        self._keep_watching = True
        self._watcher = Thread(target=self._watch)
        self._watcher.start()
        self._wait()

    def _watch(self):
        while self._should_still_watch():
            start_time = datetime.now()
            active_alarms = self._get_active_alarms()

            if active_alarms is not None:
                self._update_read_active_alarms(active_alarms)
                self._check_for_detected_alarms(active_alarms)
                self._check_for_lost_alarms(active_alarms)

            self._wait(elapsed_time=self._get_time_delta(start_time, datetime.now()))

    def _should_still_watch(self):
        return self._keep_watching

    def _get_active_alarms(self):
        try:
            return self._bts.get_active_alarms(self._bts_connection_name, self._interval)
        except (AdminApiNoResponseException, AdminApiProcedureTimeoutException, AdminApiConnectionClosedException,
                AdminApiTerminatedException, AdminApiProcedureFailureException, ConnectionError,
                ConnectTimeout, ReadTimeout, ApiExceptionLicensed, ApiException, MaxRetryError, HTTPError) as error:
            self._latest_connection_error = (self._get_timestamp(), error)

            if self._reconnect:
                self._reconnect_to_bts()

            return None

    def _reconnect_to_bts(self):
        new_bts_connection_id = int(self._bts_connection_name.split('_')[-1]) + 1
        new_bts_connection_name = 'alarms_watchdog_reconnected_{}'.format(new_bts_connection_id)

        try:
            self._bts.connect_to(self._bts_config, new_bts_connection_name, self._log_dir, self._connection_timeout,
                                 **self._bts_connection_kwargs)
        except (AdminApiConnectionClosedException, AdminApiTerminatedException, ConnectionError) as error:
            self._latest_connection_error = (self._get_timestamp(), error)
        else:
            self._bts.disconnect(self._bts_connection_name)
            self._bts_connection_name = new_bts_connection_name

    def _update_read_active_alarms(self, active_alarms):
        self._read_active_alarms = [self._convert_active_alarm_to_alarm(alarm) for alarm in active_alarms]

    def _check_for_detected_alarms(self, active_alarms):
        for active_alarm in active_alarms:
            if not self._is_active_alarm_allowed(active_alarm):
                self._add_detected_alarm(active_alarm)

    def _is_active_alarm_allowed(self, active_alarm):
        return self._is_alarm_allowed(self._convert_active_alarm_to_alarm(active_alarm))

    def _is_alarm_allowed(self, alarm):
        return alarm in self._allowed_alarms

    def _add_detected_alarm(self, active_alarm):
        alarm = self._convert_active_alarm_to_alarm(active_alarm)
        if alarm not in self._disallowed_active_alarms:
            self._detected_alarms.append(self._convert_active_alarm_to_detected_alarm(active_alarm))
            self._disallowed_active_alarms.append(alarm)
            self._run_callbacks(alarm)

    def _run_callbacks(self, alarm):
        callbacks_to_run = [callback for callback, trigger_alarms in self._callbacks.items()
                            if self._is_alarm_a_trigger(alarm, trigger_alarms)]

        for callback_to_run in callbacks_to_run:
            callback_name, callback_args, callback_kwargs = callback_to_run
            callback_kwargs = dict(callback_kwargs)

            self._log_info_message("{} detected, executing callback {} with args {} and kwargs {} on {}{}".format(
                alarm, callback_name, callback_args, callback_kwargs,
                self._bts_type, self._get_formatted_bts_ip_if_exists())
            )

            self._run_callback(callback_name, callback_args, callback_kwargs)

    @staticmethod
    def _is_alarm_a_trigger(alarm, trigger_alarms):
        return not trigger_alarms or alarm in trigger_alarms

    def _run_callback(self, callback, args, kwargs):
        callback_thread = Thread(target=callback, args=args, kwargs=kwargs)
        callback_thread.setName(callback.__name__)
        callback_thread.start()
        self._callbacks_threads.append(callback_thread)

    def _check_for_lost_alarms(self, active_alarms):
        alarms = map(self._convert_active_alarm_to_alarm, active_alarms)

        for disallowed_active_alarm in self._disallowed_active_alarms:
            if disallowed_active_alarm not in alarms:
                self._add_lost_alarm(disallowed_active_alarm)

    def _add_lost_alarm(self, alarm):
        self._lost_alarms.append(self._convert_alarm_to_lost_alarm(alarm))
        self._disallowed_active_alarms.remove(alarm)

    @staticmethod
    def _get_time_delta(start_time, end_time):
        time_delta = end_time - start_time
        return time_delta.total_seconds()

    def _wait(self, elapsed_time=0.0):
        time_delta = self._interval - elapsed_time
        sleep(time_delta if time_delta >= 0 else 0)

    def _convert_active_alarm_to_alarm(self, active_alarm):
        alarm_id, fault_id, fault_name, hw_path, severity, reason, unit_path, impacted_cells_count, fault_signature = \
            self._unpack_active_alarm(active_alarm)

        return Alarm(alarm_id=alarm_id,
                     fault_id=fault_id,
                     fault_name=fault_name,
                     hw_path=hw_path,
                     severity=severity,
                     reason=reason,
                     unit_path=unit_path,
                     impacted_cells_count=impacted_cells_count,
                     fault_signature=fault_signature)

    def _convert_active_alarm_to_detected_alarm(self, active_alarm):
        alarm_id, fault_id, fault_name, hw_path, severity, reason, unit_path, impacted_cells_count, fault_signature = \
            self._unpack_active_alarm(active_alarm)

        return DetectedAlarm(detection_time=self._get_timestamp(),
                             alarm_id=alarm_id,
                             fault_id=fault_id,
                             fault_name=fault_name,
                             hw_path=hw_path,
                             severity=severity,
                             reason=reason,
                             unit_path=unit_path,
                             impacted_cells_count=impacted_cells_count,
                             fault_signature=fault_signature)

    def _convert_alarm_to_lost_alarm(self, alarm):
        return LostAlarm(loss_time=self._get_timestamp(),
                         alarm_id=alarm.alarm_id,
                         fault_id=alarm.fault_id,
                         fault_name=alarm.fault_name,
                         hw_path=alarm.hw_path,
                         severity=alarm.severity,
                         reason=alarm.reason,
                         unit_path=alarm.unit_path,
                         impacted_cells_count=alarm.impacted_cells_count,
                         fault_signature=alarm.fault_signature)

    def _unpack_active_alarm(self, active_alarm):
        """
        Unpacks active alarm attributes.

        :param active_alarm: active alarm read from BTS, i.e.
                             {'configObjectName': '[SISOAUTO021 5G] MRBTS-50521/MNL-1/MNLENT-1/SECADM-1',
                              'faultId': 4655,
                              'faultName': 'Service account root access is enabled',
                              'faultSignature': {'category': '-',
                                                 'component': '-',
                                                 'date': '-',
                                                 'extraInfo': '-',
                                                 'info': '-',
                                                 'loadName': '-',
                                                 'minor': '-',
                                                 'resetCounter': '-',
                                                 'rfmCpri': '-',
                                                 'rfmFpga': '-',
                                                 'rfmGpp': '-',
                                                 'scope': '-'},
                              'hwPath': 'N/A',
                              'impactedCell': 'N/A',
                              'number': 7220,
                              'severity': 'Minor'}
        :type active_alarm: dict
        :return: alarm id, fault id, fault name, hw path, severity, reason, unit path, impacted cells count
        :rtype: tuple
        """
        if self._bts_type == 'CloudBts':
            return (active_alarm['alarm_id'],
                    active_alarm['fault_id'],
                    active_alarm['fault_name'],
                    None,
                    active_alarm['severity'],
                    None,
                    active_alarm['alarming_object'],
                    None,
                    None)
        else:
            return (active_alarm['number'],
                    active_alarm['faultId'],
                    active_alarm['faultName'],
                    active_alarm['hwPath'],
                    active_alarm['severity'],
                    active_alarm.get('supplAlarmInfo'),
                    active_alarm['configObjectName'],
                    active_alarm['impactedCell'],
                    active_alarm['faultSignature'])

    def _is_alarm_already_allowed(self, alarm):
        return any(allowed_alarm.matches_exactly(alarm) for allowed_alarm in self._allowed_alarms)

    def _get_report(self):
        self._log_debug_message('Getting report for {}{}'.format(
            self._bts_type, self._get_formatted_bts_ip_if_exists())
        )
        report = '\n'
        alarms_history = self._detected_alarms + self._lost_alarms
        alarms_history.sort(key=lambda a: a.time)

        for event in alarms_history:
            report += str(event) + '\n'

        return report

    def _register_callback(self, trigger_alarms, callback_name, callback_args, callback_kwargs):
        callback = (callback_name, callback_args, tuple((name, value) for name, value in callback_kwargs.items()))

        if callback not in self._callbacks:
            self._callbacks[callback] = trigger_alarms if trigger_alarms else []
        elif callback in self._callbacks and (not trigger_alarms or not self._callbacks[callback]):
            self._callbacks[callback] = []
        elif callback in self._callbacks and trigger_alarms:
            not_registered_trigger_alarms = [trigger_alarm for trigger_alarm in trigger_alarms
                                             if not self._is_trigger_alarm_already_registered(trigger_alarm, callback)]
            self._callbacks[callback].extend(not_registered_trigger_alarms)

    def _is_trigger_alarm_already_registered(self, trigger_alarm, callback):
        registered_trigger_alarms = self._callbacks[callback]
        return any(registered_alarm.matches_exactly(trigger_alarm) for registered_alarm in registered_trigger_alarms)

    def _stop_watcher(self):
        self._stop_callbacks_threads()
        self._stop_watcher_thread()

    def _stop_callbacks_threads(self):
        for callback_thread in self._callbacks_threads:
            self._log_debug_message('Stopping callback thread: {} on {}{}'.format(
                callback_thread.name, self._bts_type, self._get_formatted_bts_ip_if_exists())
            )
            callback_thread.join()

    def _stop_watcher_thread(self):
        self._log_info_message('Stopping watcher thread on {}{}'.format(
            self._bts_type, self._get_formatted_bts_ip_if_exists())
        )
        self._keep_watching = False

        if self._watcher is not None:
            self._watcher.join()

    def _disconnect_from_bts(self):
        self._log_info_message('Disconnecting from {}{}'.format(
            self._bts_type, self._get_formatted_bts_ip_if_exists())
        )

        if self._bts is not None:
            self._bts.disconnect(self._bts_connection_name)

    def _reset(self):
        self._log_debug_message('Resetting to default state on {}{}'.format(
            self._bts_type, self._get_formatted_bts_ip_if_exists())
        )
        self._allowed_alarms = []
        self._detected_alarms = []
        self._lost_alarms = []
        self._read_active_alarms = []
        self._disallowed_active_alarms = []
        self._watcher = None
        self._keep_watching = False
        self._interval = 0.0
        self._reconnect = False
        self._callbacks = {}
        self._callbacks_threads = []
        self._bts_config = None
        self._bts = None
        self._bts_connection_kwargs = {}
        self._latest_connection_error = None
        self._log_dir = ''

    def _log_allowed_alarms(self):
        self._log_debug_message("Currently allowed alarms on {}{}: {}".format(
            self._bts_type, self._get_formatted_bts_ip_if_exists(), self._allowed_alarms)
        )

    def _log_read_active_alarms(self):
        self._log_debug_message("Currently active alarms on {}{}: {}".format(
            self._bts_type, self._get_formatted_bts_ip_if_exists(), self._read_active_alarms)
        )

    def _log_latest_connection_error(self):
        self._log_debug_message('Latest connection error while getting active alarms from {}{}: {}'.format(
            self._bts_type, self._get_formatted_bts_ip_if_exists(), self._latest_connection_error))

    def _log_info_message(self, message):
        self._logger.info('{} (@{})'.format(message, id(self)))

    def _log_debug_message(self, message):
        self._logger.debug('{} (@{})'.format(message, id(self)))

    def _is_alarm_active(self, alarm_to_check):
        return alarm_to_check in self._read_active_alarms

    def _is_alarm_inactive(self, alarm_to_check):
        return alarm_to_check not in self._read_active_alarms

    def _are_alarms_active(self, alarms):
        return all(alarm in self._read_active_alarms for alarm in alarms)

    def _are_alarms_inactive(self, alarms):
        return not any(alarm in self._read_active_alarms for alarm in alarms)

    def _get_formatted_bts_ip_if_exists(self):
        return " ({})".format(self._bts.host) if self._bts and self._bts.host else ""

    @staticmethod
    def _wait_for(condition_callback, expected_value, timeout):
        start_time = time()
        while time() - start_time < timeout:
            if condition_callback(expected_value):
                return True
            sleep(0.25)
        return False

    @staticmethod
    def _get_timestamp():
        return str(datetime.now())
